import type { TourHint, TourStep } from './tourContent';
export type EngineState = { path: string[]; index: number; status: 'idle' | 'active' | 'paused' | 'done' | 'dismissed'; done: string[]; skipped: string[]; events: string[] };
export type Rect = { x: number; y: number; w: number; h: number };
export const isInteractive: (id: string) => boolean;
export const words: (s: string) => number;
export function pathFor(goal?: string): string[];
export function init(o?: { goal?: string; saved?: Partial<EngineState> | null }): EngineState;
export const current: (s: EngineState) => (TourStep & { id: string }) | null;
export const start: (s: EngineState) => EngineState;
export const next: (s: EngineState) => EngineState;
export const back: (s: EngineState) => EngineState;
export const skip: (s: EngineState) => EngineState;
export const resume: (s: EngineState) => EngineState;
export const dismiss: (s: EngineState) => EngineState;
export const replay: (s: EngineState) => EngineState;
export function skipMissing(s: EngineState): EngineState;
export function onEvent(s: EngineState, event: string): { state: EngineState; completed: string | null; cheer: string };
export function detectEvent(method: string, url: string): string | null;
export function checklistState(events?: string[]): { items: { id: string; label: string; event: string; done: boolean }[]; done: number; total: number; complete: boolean; label: string; reward: { text: string; sticker: string } | null };
export function hintsFor(screen: string, seen?: string[]): TourHint[];
export const allHints: (screen: string) => TourHint[];
export function whatsNewFor(seen?: string[], buildNumber?: number): { id: string; since: string; anchor: string; text: string }[];
export function mergeSaved(a?: any, b?: any): any;
export function placeTip(rect: Rect, view: { w: number; h: number }, tip: { w: number; h: number }, gap?: number, margin?: number): { x: number; y: number; side: 'below' | 'above' };
export function usableRect(rect: Rect | null, view: { w: number; h: number }): boolean;
